window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[174]={"id":"174","numero":174,"titre":"Pathologie infectieuse chez le migrant — adulte / enfant","objectifs":[{"id":"174-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’un migrant (personne immigrée)","contenu":"<div class=\"notion-course\"><ul><li>Migrant est un terme large décrivant un déplacement durable de résidence ; réfugié, demandeur d’asile et personne sans titre de séjour correspondent à des situations distinctes.</li><li>Au sens statistique INSEE, un immigré est né étranger à l’étranger et réside en France ; il peut avoir acquis la nationalité française. Ne pas confondre immigré et étranger, ni imposer un délai universel d’un an à cette définition.</li><li>L’évaluation de santé est individuelle : trajectoire, pays et conditions de vie, expositions, accès aux soins, langue, traumatismes et attentes de la personne.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-174.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 174</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.ameli.fr/assure/droits-demarches/europe-international/protection-sociale-france/demandeur-d-asile\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · demandeurs d’asile et soins urgents</a></li><li><a href=\"https://www.hcsp.fr/explore.cgi/avisrapportsdomaine?clefr=1528\" target=\"_blank\" rel=\"noopener noreferrer\">HCSP · recommandations sanitaires aux voyageurs 2026</a></li></ul></details>","frequence":0},{"id":"174-2","rang":"A","rubrique":"Physiopathologie","titre":"Connaître les principales pathologies infectieuses des migrants","contenu":"<div class=\"notion-course\"><p><span>Les</span> pathologies infectieuses du migrant se classent selon leur <strong>mécanisme d'acquisition</strong> : infections d'importation (pays d'origine) et infections acquises sur le territoire national.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">1 · Infections d'importation</h4>\n      <p>Contractées dans le pays d'origine. Concernent surtout <span>les</span> travailleurs migrants récemment arrivés et leur famille, les réfugiés politiques, les personnes en situation irrégulière, et les migrants <strong>retournant régulièrement</strong> au pays (VFR — <em>visit friends and relatives</em>).</p>\n      <table>\n        <thead><tr><th>Catégorie</th><th>Principales entités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Parasites</span></strong></td>\n            <td>\n              <strong>Protozooses :</strong> <span>paludisme</span> ; amœbose ; giardose ; <span>leishmanioses</span> (cutanée, viscérale) ; trypanosomoses — maladie du sommeil (Afrique) et maladie de Chagas (Amérique)<br>\n              <strong>Helminthoses intestinales :</strong> ascaridiose ; <span>ankylostomose</span> (<span><span class=\"nc-red nc-bold\">anémie par carence martiale</span></span>) ; strongyloïdose (anguillulose) ; téniasis<br>\n              <strong>Helminthoses tissulaires :</strong> filarioses (loase, filarioses lymphatiques, onchocercose) ; <span>schistosomoses</span> ; hydatidose hépatique\n            </td>\n          </tr>\n          <tr><td><strong><span>Champignons</span></strong></td><td>Dermatophyties des phanères et de la peau glabre (teignes)</td></tr>\n          <tr><td><strong><span>Bactéries</span></strong></td><td><span>Tuberculose</span> ; lèpre</td></tr>\n          <tr><td><strong><span>Virus</span></strong></td><td><span>VIH</span> ; <span>VHB</span> ; <span>VHC</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">2 · Infections acquises sur le territoire national</h4>\n      <p>Liées aux conditions socio-économiques défavorables ; maladies usuelles, souvent <strong>plus fréquentes et plus graves</strong> :</p>\n      <ul>\n        <li><span>Infections respiratoires et intestinales</span>, bactériennes et virales</li>\n        <li><span><span class=\"nc-purple nc-bold\">Tuberculose</span></span> <span>acquise</span> en France (communauté de vie)</li>\n        <li><span>IST</span> — l'acquisition du <span>VIH</span> et de la <span>tuberculose</span> n'est pas rare</li>\n        <li>Infections <span>pneumococciques</span> et <span>salmonelloses non typhiques</span> chez le <span>drépanocytaire</span></li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        <strong><span>Urgence</span> — <span>neuropaludisme</span>.</strong> Devant une <span>fièvre</span> + <span>trouble de conscience</span> au retour d'une zone d'endémie palustre : <span>frottis sanguin + goutte épaisse</span> en urgence (&lt;<span> 2 h</span>). Le <span>paludisme</span> grave à <em><span>P. falciparum</span></em> est l'urgence à <span>ne jamais</span> rater.\n      </div>\n      <div class=\"callout callout-warn\">\n        <strong>Piège — strongyloïdose et <span>corticoïdes</span>.</strong> <em>Strongyloides stercoralis</em> peut <strong>s'auto-infester</strong> : sous <span>corticothérapie</span> ou immunosuppression, risque d'<span>hyperinfection mortelle</span>. Dépister la <span>sérologie anguillulose</span> avant toute <span>corticothérapie</span> chez un migrant de zone d'endémie.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 170 — <span>Paludisme</span> · 169 — <span><span class=\"nc-purple_bg\">VIH</span></span> · 167 — Hépatites virales · 159 — <span>Tuberculose</span> Enfant / Adulte</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-174.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 174</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.ameli.fr/assure/droits-demarches/europe-international/protection-sociale-france/demandeur-d-asile\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · demandeurs d’asile et soins urgents</a></li><li><a href=\"https://www.hcsp.fr/explore.cgi/avisrapportsdomaine?clefr=1528\" target=\"_blank\" rel=\"noopener noreferrer\">HCSP · recommandations sanitaires aux voyageurs 2026</a></li></ul></details>","frequence":0},{"id":"174-3","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les arguments épidémio-cliniques et les stratégies d’examens complémentaires pour identifier les principales pathologies infectieuses des migrants","contenu":"<div class=\"notion-course\"><p>L'identification d'une pathologie infectieuse chez le migrant repose sur le croisement de trois axes : <strong>zone géographique d'origine</strong> × <strong>délai depuis l'arrivée</strong> × <strong>symptôme d'appel</strong>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Arguments épidémiologiques</h4>\n      <ul>\n        <li><strong>Zone d'origine</strong> — oriente le spectre <span>parasitaire</span> (l'<span>Afrique sub-saharienne</span> cumule le risque maximal et le plus de pathologies).</li>\n        <li><strong>Délai depuis l'arrivée</strong> — une infection d'importation se révèle volontiers dans <span>les</span> premiers mois ou années.</li>\n        <li><strong>Retour régulier au pays</strong> (VFR) — réexposition et perte de l'immunité antérieurement <span>acquise</span>.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Symptôme d'appel → examens à orienter</h4>\n      <table>\n        <thead><tr><th>Symptôme d'appel</th><th>Stratégie d'examens complémentaires</th></tr></thead>\n        <tbody>\n          <tr><td><span>Fièvre</span> (origine géographique compatible)</td><td><span>Frottis sanguin + goutte épaisse</span> ; ou <span>TDR-paludisme</span> ; ou <span>PCR</span> si disponible — à répéter si premier examen négatif</td></tr>\n          <tr><td><span>Troubles digestifs</span> / <span>diarrhée</span></td><td><span>3 examens parasitologiques des selles (EPS)</span> sur <span>3 jours</span> différents</td></tr>\n          <tr><td><span>Hématurie</span></td><td><span><span class=\"nc-blue_bg\">Parasitologie des urines</span></span> + <span><span class=\"nc-blue_bg\">sérologie de la schistosomose</span></span></td></tr>\n          <tr><td><span>Anémie microcytaire</span> inexpliquée</td><td>Évoquer <span>ankylostomose</span> et schistosomose digestive (EPS, <span>sérologie</span>) <strong>avant</strong> <span>endoscopie</span></td></tr>\n          <tr><td><span>Fièvre + splénomégalie + pancytopénie</span></td><td><span>Sérologie leishmaniose</span> + recherche d'<span>amastigotes</span> sur <span>ponction</span> médullaire</td></tr>\n          <tr><td><span>Éosinophilie</span></td><td>Bilan d'helminthose : <span class=\"nc-yellow_bg\">EPS</span>, <span>sérologies</span> (anguillulose, schistosomose, filaires)</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Associations cliniques discriminantes</h4>\n      <table>\n        <thead><tr><th>Pathologie</th><th>Mot-clé évocateur</th></tr></thead>\n        <tbody>\n          <tr><td><span>Paludisme</span></td><td><span>Fièvre</span> au retour de zone d'endémie ; <span>thrombopénie</span> ; <span>splénomégalie</span></td></tr>\n          <tr><td><span>Amœbose</span></td><td><span>Diarrhée</span> <span>glairo-sanglante</span> ; <span>abcès hépatique amibien</span> (<span>échographie</span>)</td></tr>\n          <tr><td><span>Schistosomose</span></td><td><span>Hématurie macroscopique terminale</span> (<em>S. haematobium</em>) ; baignade en eau douce</td></tr>\n          <tr><td><span>Ankylostomose</span></td><td><span>Anémie ferriprive chronique</span> inexpliquée ; transmission transcutanée</td></tr>\n          <tr><td><span>Strongyloïdose</span></td><td><span>Larva currens</span> ; <span>hyperinfection sous corticoïdes</span></td></tr>\n          <tr><td><span>Leishmaniose viscérale</span></td><td><span>Fièvre prolongée + splénomégalie majeure + pancytopénie</span> (Kala-azar)</td></tr>\n          <tr><td><span>Cysticercose</span> (<em>T. solium</em>)</td><td><span>Crises convulsives d'apparition tardive</span> ; <span>IRM</span> : kystes en cocarde</td></tr>\n          <tr><td><span>Filarioses</span></td><td><span>Œdème</span> de Calabar (<em>Loa loa</em>) ; éléphantiasis (<em>W. bancrofti</em>) ; cécité des rivières (<em>Onchocerca</em>)</td></tr>\n          <tr><td><span>Maladie de Chagas</span></td><td><span>Cardiomyopathie dilatée</span> + mégaœsophage / mégacolon ; Amérique latine</td></tr>\n          <tr><td><span>Tuberculose</span></td><td><span>Toux &gt; 3 semaines</span> ; <span>AEG</span> ; sueurs nocturnes ; formes extra-pulmonaires fréquentes</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>Piège — leishmaniose viscérale.</strong> Devant <span>fièvre prolongée + splénomégalie majeure + pancytopénie</span> chez un migrant, le Kala-azar est le <span>principal diagnostic différentiel d'une leucémie aiguë</span>. Évoquer la <span>sérologie leishmaniose</span> et la recherche d'amastigotes avant de conclure à une hémopathie.\n      </div>\n      <div class=\"callout callout-warn\">\n        <strong>Piège — cysticercose cérébrale.</strong> Une <span>épilepsie d'apparition tardive</span> chez un migrant de zone d'endémie (<em>T. solium</em>) doit faire évoquer une neurocysticercose : <span>IRM cérébrale</span> + <span>sérologie</span> cysticercose.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 170 — <span>Paludisme</span> · 176 — <span>Diarrhée</span> infectieuse · 159 — <span>Tuberculose</span> Enfant / Adulte</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-174.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 174</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.ameli.fr/assure/droits-demarches/europe-international/protection-sociale-france/demandeur-d-asile\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · demandeurs d’asile et soins urgents</a></li><li><a href=\"https://www.hcsp.fr/explore.cgi/avisrapportsdomaine?clefr=1528\" target=\"_blank\" rel=\"noopener noreferrer\">HCSP · recommandations sanitaires aux voyageurs 2026</a></li></ul></details>","frequence":0},{"id":"174-4","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités d’accès aux soins des migrants","contenu":"<div class=\"notion-course\"><ul><li>Faciliter l’accès effectif aux soins, avec interprétariat professionnel et accompagnement social. Vérifier les droits actuels auprès de la CPAM/PASS : ils dépendent de la situation administrative et de résidence.</li><li>Demandeur d’asile majeur : couverture après délai de résidence prévu, avec dispositif de soins urgents pendant l’attente ; les enfants mineurs bénéficient de soins sans ce délai. Les soins urgents ne se limitent pas au seul risque vital immédiat : ils couvrent aussi le risque d’altération grave et durable, ainsi que des situations liées à la grossesse et aux mineurs.</li><li>La présence d’une origine étrangère n’impose pas un isolement hospitalier. Recherche de BHRe et précautions selon exposition, notamment hospitalisation récente à l’étranger, portage connu et recommandations d’hygiène.</li><li>Évaluer les urgences médicales et psychiques, la continuité des traitements et les obstacles au suivi ; les démarches administratives ne doivent pas retarder un soin urgent.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-174.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 174</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.ameli.fr/assure/droits-demarches/europe-international/protection-sociale-france/demandeur-d-asile\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · demandeurs d’asile et soins urgents</a></li><li><a href=\"https://www.hcsp.fr/explore.cgi/avisrapportsdomaine?clefr=1528\" target=\"_blank\" rel=\"noopener noreferrer\">HCSP · recommandations sanitaires aux voyageurs 2026</a></li></ul></details>","frequence":1},{"id":"174-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principales pathologies à dépister chez les migrants","contenu":"<div class=\"notion-course\"><p>Le <span>dépistage</span> du migrant primo-arrivant associe un <strong>bilan systématique commun</strong> et un <strong>bilan contextuel</strong> orienté par la zone d'origine et la clinique.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Bilan à proposer au primo-arrivant, adapté à la personne, aux expositions et aux recommandations</h4>\n      <table>\n        <thead><tr><th>Examen</th><th>Cible du <span>dépistage</span></th></tr></thead>\n        <tbody>\n          <tr><td><span>Sérologies <span class=\"nc-purple_bg\">VIH</span>, <span class=\"nc-purple_bg\">VHB</span>, <span class=\"nc-purple_bg\">VHC</span></span></td><td><span><span class=\"nc-purple_bg\">VIH</span></span>, portage chronique du <span><span class=\"nc-purple_bg\">VHB</span></span> (zone Afrique sub-saharienne +++), hépatite C</td></tr>\n          <tr><td><span>Glycémie capillaire</span></td><td><span>Diabète</span> souvent méconnu</td></tr>\n          <tr><td><span>Bandelette urinaire (BU)</span></td><td><span>Infection urinaire</span> ; <span>hématurie</span> (schistosomose) ; <span>protéinurie</span></td></tr>\n          <tr><td><span>NFS</span></td><td>Cytopénies ; anémie martiale ; <span>éosinophilie</span> (helminthoses)</td></tr>\n          <tr><td><span><span class=\"nc-blue_bg\">RXT</span></span> + <span>IDR ou IGRA</span> chez <span>les</span> <span><span class=\"nc-pink nc-bold\">&lt; 18 ans</span></span></td><td>Si provenance d'un pays à <span>incidence</span> élevée de <span><span class=\"nc-purple nc-bold\">tuberculose</span></span> : recherche de TB-maladie ou d'infection tuberculeuse latente</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Bilan contextuel</h4>\n      <table>\n        <thead><tr><th>Contexte</th><th>Examens à ajouter</th></tr></thead>\n        <tbody>\n          <tr><td>Origine d'Afrique sub-saharienne</td><td><span><span class=\"nc-blue_bg\">Sérologie de la schistosomose</span></span></td></tr>\n          <tr><td><span>Fièvre</span> + origine géographique compatible</td><td><span>Frottis sanguin + goutte épaisse</span> ; ou frottis + <span>TDR</span> ; ou <span>PCR</span></td></tr>\n          <tr><td><span>Troubles digestifs</span> (<span>diarrhée</span>)</td><td><span><span class=\"nc-blue_bg\">3 EPS</span></span></td></tr>\n          <tr><td><span>Hématurie</span></td><td><span><span class=\"nc-blue_bg\">Parasitologie des urines</span></span> + <span><span class=\"nc-blue_bg\">sérologie</span></span><span class=\"nc-blue_bg\"> de la schistosomose</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Cartographie — pathologies à dépister selon la zone d'origine</h4>\n      <p>Transcription de la matrice Pilly 2023 (certains éléments sont de rang A, B ou C).</p>\n      <table>\n        <thead><tr><th>Zone d'origine</th><th>Pathologies à dépister</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Afrique sub-saharienne</strong><br><span>Risque maximal</span></td>\n            <td>\n              <strong>Bactéries / virus :</strong> <span><span class=\"nc-purple nc-bold\">tuberculose</span></span> ; portage chronique du <span><span class=\"nc-purple_bg\">VHB</span></span> fréquent ; <span><span class=\"nc-purple_bg\">VHC</span></span> ; <span><span class=\"nc-purple_bg\">VIH</span></span> (<span>prévalence</span> élevée)<br>\n              <strong>Helminthoses :</strong> ascaridiose ; ankylostomose ; anguillulose ; téniasis ; filarioses (<em>Loa loa</em>, <em>W. bancrofti</em>, <em>Onchocerca</em>) ; schistosomoses urinaire et intestinale ; hydatidose hépatique<br>\n              <strong>Protozooses :</strong> <span>paludisme</span> (surtout <em><span>P. falciparum</span></em>) ; leishmanioses ; trypanosomose africaine (maladie du sommeil) ; amœbose ; giardose<br>\n              <strong>Ectoparasites :</strong> <span>gale</span> (surtout chez l'enfant)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Maghreb / Afrique du Nord</strong></td>\n            <td>\n              <strong>Bactéries / virus :</strong> <span>tuberculose</span> ; <span><span class=\"nc-purple_bg\">VHB</span></span> ; <span><span class=\"nc-purple_bg\">VHC</span></span> ; <span class=\"nc-purple_bg\">VIH</span><br>\n              <strong>Helminthoses :</strong> téniasis (<em>T. saginata</em>) ; schistosomose urinaire (<em>S. haematobium</em>) ; hydatidose hépatique<br>\n              <strong>Protozooses :</strong> <span>paludisme</span> à <em><span>P. falciparum</span></em> (Sahel sud) ; leishmanioses cutanée et viscérale ; amœbose ; giardose<br>\n              <strong>Ectoparasites :</strong> <span>gale</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Asie du Sud-Est</strong></td>\n            <td>\n              <strong>Bactéries / virus :</strong> <span>tuberculose</span> ; <span><span class=\"nc-purple_bg\">VHB</span></span> ; <span><span class=\"nc-purple_bg\">VHC</span></span> ; <span class=\"nc-purple_bg\">VIH</span><br>\n              <strong>Helminthoses :</strong> ascaridiose ; ankylostomose ; anguillulose ; téniasis ; filariose lymphatique (<em>W. bancrofti</em>) ; schistosomose intestinale (<em>S. japonicum</em>, <em>S. mekongi</em>) ; hydatidose<br>\n              <strong>Protozooses :</strong> <span>paludisme</span> (<em><span>P. falciparum</span></em>, <em>P. vivax</em>) ; leishmaniose viscérale (Kala-azar, Inde) ; amœbose ; giardose<br>\n              <strong>Ectoparasites :</strong> <span>gale</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Amérique latine + Guyane</strong></td>\n            <td>\n              <strong>Bactéries / virus :</strong> <span>tuberculose</span> ; <span><span class=\"nc-purple_bg\">VHB</span></span> ; <span><span class=\"nc-purple_bg\">VHC</span></span> ; <span class=\"nc-purple_bg\">VIH</span><br>\n              <strong>Helminthoses :</strong> ascaridiose ; ankylostomose ; anguillulose ; téniasis ; filarioses (<em>W. bancrofti</em>, <em>Onchocerca</em>) ; schistosomose intestinale (<em>S. mansoni</em>) ; hydatidose<br>\n              <strong>Protozooses :</strong> <span>paludisme</span> (<em><span>P. falciparum</span></em>, <em>P. vivax</em>) ; leishmanioses ; <span>maladie de Chagas</span> (<em>T. cruzi</em>) ; amœbose ; giardose<br>\n              <strong>Ectoparasites :</strong> <span>gale</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Antilles (Guadeloupe / Martinique)</strong></td>\n            <td>\n              <strong>Bactéries / virus :</strong> <span>tuberculose</span> (cas particulier — <span>incidence</span> proche de la métropole) ; <span><span class=\"nc-purple_bg nc-bold\">VHB</span></span> ; <span><span class=\"nc-purple_bg nc-bold\">VHC</span></span> ; VIH<br>\n              <strong>Helminthoses :</strong> téniasis (<em>T. saginata</em>) ; filariose lymphatique (<em>W. bancrofti</em>)<br>\n              <strong>Protozooses :</strong> amœbose ; giardose<br>\n              <strong>Ectoparasites :</strong> <span>gale</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Focus <span>tuberculose</span> — <span>épidémiologie</span> à connaître</h4>\n      <ul>\n        <li><span>50 %</span> des cas de <span><span class=\"nc-purple nc-bold\">tuberculose</span></span> en France sont diagnostiqués chez des <strong>migrants</strong>.</li>\n        <li>Parmi eux : <span>50 %</span> dans <span>les</span> <span>5 premières années</span> suivant l'arrivée, <span>25 %</span> dans les <span>2 premières années</span>.</li>\n        <li>Origines principales : Afrique sub-saharienne (<span>40 %</span>) · Maghreb (<span>30 %</span>).</li>\n        <li>Mécanisme dominant : <strong>réactivation d'une infection tuberculeuse latente</strong> contractée au pays.</li>\n        <li>Particularités : <span>formes extra-pulmonaires</span> plus fréquentes ; <span>BK multirésistante</span> (résistance à l'<span>isoniazide</span> + la <span>rifampicine</span>) plus fréquente.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Rang A — où réaliser le bilan ?</strong> Laboratoire sur prescription si protection maladie ; <span class=\"nc-yellow_bg\">Centres d'Examens de Santé de la Sécurité sociale</span> (bilan gratuit) ; <strong><span><span class=\"nc-yellow_bg\">CeGIDD</span></span>, <span><span class=\"nc-yellow_bg\">CLAT</span></span>, <span><span class=\"nc-yellow_bg\">PASS</span></span></strong> qui réalisent une grande partie de ces bilans <span>y compris chez les personnes dont les droits sociaux n'ont pas été ouverts</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 159 — <span>Tuberculose</span> Enfant / Adulte · 169 — <span><span class=\"nc-purple_bg\">VIH</span></span> · 167 — Hépatites virales · 170 — <span>Paludisme</span></em></p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Les dépistages sont adaptés aux expositions et au parcours, avec accord de la personne ; les cartes historiques illustrent des risques et ne remplacent pas une évaluation actuelle. Ne pas prescrire automatiquement l’ensemble des examens parasitaires à toute personne migrante.</li><li>Les chiffres et la cartographie du tableau sont des repères historiques du Pilly 2023 ; ils ne constituent pas une surveillance épidémiologique en temps réel ni une liste d’examens à imposer selon la seule origine.</li></ul></div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-174.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 174</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.ameli.fr/assure/droits-demarches/europe-international/protection-sociale-france/demandeur-d-asile\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · demandeurs d’asile et soins urgents</a></li><li><a href=\"https://www.hcsp.fr/explore.cgi/avisrapportsdomaine?clefr=1528\" target=\"_blank\" rel=\"noopener noreferrer\">HCSP · recommandations sanitaires aux voyageurs 2026</a></li></ul></details>","frequence":1},{"id":"174-6","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de la prévention à mettre en place chez les migrants","contenu":"<div class=\"notion-course\"><p>La prévention chez le migrant combine le <span>dépistage</span> et le traitement de l'<strong>entourage</strong>, l'éducation à l'hygiène, la prévention des <span>IST</span> et du <span>paludisme</span>.</p>\n\n      <table>\n        <thead><tr><th>Volet</th><th>Mesures</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Dépistage</span> de l'entourage</strong></td>\n            <td>\n              <span>Dépistage</span> par <strong>examen médical du patient et de son entourage</strong><br>\n              Dépister et traiter l'entourage en cas de maladie contagieuse : <span><span class=\"nc-purple nc-bold\">tuberculose</span></span>, <span>IST</span>, <span>teigne</span>, <span>parasitoses intestinales</span><br>\n              <span>Vacciner l'entourage contre l'hépatite B</span> en cas de positivité\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Hygiène alimentaire</strong></td>\n            <td>Lavage des mains ; cuisson des aliments ; expliquer <span>les</span> principaux risques, leurs modes de transmission et la prévention</td>\n          </tr>\n          <tr>\n            <td><strong>Prévention des <span>IST</span></strong></td>\n            <td><span>Préservatif masculin ou féminin</span> ; <span>PrEP</span> ; aide d'un interprète ; rôle des associations</td>\n          </tr>\n          <tr>\n            <td><strong>Prévention du <span>paludisme</span></strong></td>\n            <td><span>Prophylaxie antipalustre</span> en cas de retour dans le pays d'origine ; expliquer le mode de transmission de la maladie</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège — le migrant qui retourne au pays (VFR).</strong> Le migrant qui rentre dans son pays d'origine n'est <span>plus immunisé</span> contre le <span>paludisme</span> : il doit recevoir une <span>prophylaxie antipalustre</span> comme tout voyageur, et une <span>mise à jour vaccinale</span> adaptée à la destination.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 162 — <span>IST</span> · 170 — <span>Paludisme</span></em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-174.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 174</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.ameli.fr/assure/droits-demarches/europe-international/protection-sociale-france/demandeur-d-asile\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · demandeurs d’asile et soins urgents</a></li><li><a href=\"https://www.hcsp.fr/explore.cgi/avisrapportsdomaine?clefr=1528\" target=\"_blank\" rel=\"noopener noreferrer\">HCSP · recommandations sanitaires aux voyageurs 2026</a></li></ul></details>","frequence":0},{"id":"174-7","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principaux vaccins à mettre à jour","contenu":"<div class=\"notion-course\"><p>La mise à jour vaccinale du migrant vise d'abord le <strong><span>rattrapage du calendrier vaccinal français</span></strong>, complété par des vaccinations ciblées selon le <span>terrain</span> et le projet de vie.</p>\n\n      <table>\n        <thead><tr><th>Population / situation</th><th>Vaccins</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Tous <span>les</span> migrants</strong></td><td>Mise à jour et <span>rattrapages</span> pour satisfaire le <strong><span>calendrier vaccinal</span> français</strong> en vigueur</td></tr>\n          <tr><td><strong><span>Drépanocytaires</span></strong></td><td><span>Pneumocoque</span> + <span>grippe</span></td></tr>\n          <tr><td><strong><span>Sujets aspléniques</span></strong></td><td><span>Pneumocoque</span> + <span>méningocoque</span> + <em><span>Haemophilus</span> influenzae</em> b + <span>grippe</span></td></tr>\n          <tr><td><strong>Projet de pèlerinage à La Mecque</strong></td><td><span>Méningocoque</span></td></tr>\n          <tr><td><strong>Retour en zone d'endémie amarile</strong></td><td><span>Fièvre jaune</span></td></tr>\n          <tr><td><strong>Entourage d'un sujet atteint d'<span>hépatite B</span></strong></td><td><span>Vaccination</span> de l'<strong>entourage familial</strong> contre l'<span>hépatite B</span></td></tr>\n          <tr><td><strong>BCG</strong></td><td><span>BCG</span> chez <span>les</span> sujets de <span>&lt; 15 ans</span> migrants nés dans un pays de <span>forte prévalence</span>, et chez les enfants nés en France d'un parent migrant issu d'un pays de <span>forte endémie</span></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> <span>Les</span> carnets de <span>vaccination</span> du pays d'origine sont de fiabilité variable : recueillir les vaccinations déjà réalisées, puis compléter selon le calendrier français. Une vaccination dont la preuve manque est considérée comme non faite.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 146 — <span>Vaccination</span></em></p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Un schéma vaccinal documenté et valide compte : ne pas recommencer systématiquement une série. En l’absence de document, organiser un rattrapage adapté à l’âge et au calendrier, sans présumer la fiabilité d’un carnet à partir de la seule nationalité.</li></ul></div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-174.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 174</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.ameli.fr/assure/droits-demarches/europe-international/protection-sociale-france/demandeur-d-asile\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · demandeurs d’asile et soins urgents</a></li><li><a href=\"https://www.hcsp.fr/explore.cgi/avisrapportsdomaine?clefr=1528\" target=\"_blank\" rel=\"noopener noreferrer\">HCSP · recommandations sanitaires aux voyageurs 2026</a></li></ul></details>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-clinique\">Paludisme</span> grave — <span class=\"kw-alerte\">urgence</span> vitale</strong></p><ul><li>toute <span class=\"kw-clinique\">fièvre</span> chez un migrant d’origine géographique compatible impose d’<span class=\"kw-ttt\">éliminer un paludisme EN PREMIER</span></li><li><span class=\"kw-bio\">frottis sanguin + goutte épaisse</span> en <span class=\"kw-alerte\">urgence</span> (± <span class=\"kw-bio\">TDR</span> ou <span class=\"kw-bio\">PCR</span> si disponible)</li><li><span class=\"kw-alerte\">neuropaludisme</span> (<span class=\"kw-etio\">P. falciparum</span>) = <span class=\"kw-alerte\">urgence vitale</span></li></ul><p><strong>Première consultation de l’enfant migrant</strong></p><ul><li>à réaliser rapidement, dans le <span class=\"kw-chiffre\">&lt; 1 mois</span> suivant l’arrivée</li></ul><p><strong>Avant toute <span class=\"kw-ttt\">corticothérapie</span></strong></p><ul><li>dépister une <span class=\"kw-etio\">anguillulose</span> (<span class=\"kw-etio\">Strongyloides stercoralis</span>) — <span class=\"kw-clinique\">les</span> <span class=\"kw-ci\">corticoïdes</span> exposent à une <span class=\"kw-alerte\">hyperinfection</span> par auto-infestation</li></ul><p><strong>Soins urgents</strong></p><ul><li>migrant hors AME / PUMa : prise en charge possible uniquement si <span class=\"kw-alerte\">pronostic vital engagé</span></li></ul>","hospit":"<p><strong>Couverture maladie — 3 dispositifs à ne pas confondre</strong></p><ul><li><span class=\"kw-def\">AME</span> (Aide Médicale de l’État) : présence <span class=\"kw-chiffre\">&gt; 3 mois</span> + absence de titre de séjour valide + faibles ressources</li><li><span class=\"kw-def\">PUMa</span> (Protection Universelle Maladie) : situation régulière <span class=\"kw-chiffre\">&gt; 3 mois</span> OU demandeur d’asile</li><li>Dispositif « <span class=\"kw-def\">soins urgents</span> » : autres cas, uniquement si <span class=\"kw-alerte\">pronostic vital engagé</span></li></ul><p><strong>Structures de soins gratuites</strong></p><ul><li><span class=\"kw-def\">PASS</span> (Permanences d’Accès aux Soins de Santé) — accueil hospitalier des personnes précaires</li><li><span class=\"kw-def\">CeGIDD</span> — <span class=\"kw-def\">dépistage</span> <span class=\"kw-bio\">VIH / VHB / VHC</span> et <span class=\"kw-clinique\">IST</span>, gratuit et anonyme</li><li><span class=\"kw-def\">CLAT</span> — <span class=\"kw-def\">dépistage</span> et prise en charge de la <span class=\"kw-etio\">tuberculose</span></li><li><span class=\"kw-def\">PMI</span>, <span class=\"kw-def\">CPEF</span>, <span class=\"kw-def\">CMP</span> (psychotraumatisme), centres de <span class=\"kw-ttt\">vaccination</span></li><li>Conseil Départemental (Direction des actions de santé) pour l’offre locale de santé</li></ul><p><strong>Enfant / mineur non accompagné</strong></p><ul><li>tout <span class=\"kw-def\">MNA</span> (mineur isolé étranger) doit être <span class=\"kw-alerte\">mis à l’abri et protégé par l’ASE</span> (Aide Sociale à l’Enfance) — jamais orienté seul</li><li>si <span class=\"kw-alerte\">hospitalisation</span> : <span class=\"kw-alerte\">isolement en chambre seule</span> jusqu’à vérification de l’absence de portage de <span class=\"kw-bio\">bactéries multirésistantes (BMR)</span></li></ul><p><strong>Interprète</strong></p><ul><li>recours fréquent à un <strong>interprète professionnel</strong>, extérieur à l’entourage, à toutes <span class=\"kw-clinique\">les</span> étapes</li></ul>","redflags":"<ul><li><span class=\"kw-clinique\">Fièvre</span> + <span class=\"kw-alerte\">trouble de la conscience</span> au retour de zone d’endémie → <span class=\"kw-alerte\">neuropaludisme</span> (<span class=\"kw-etio\">P. falciparum</span>), <span class=\"kw-alerte\">urgence</span> vitale</li><li><span class=\"kw-clinique\">Fièvre prolongée</span> + <span class=\"kw-clinique\">splénomégalie</span> + <span class=\"kw-bio\">pancytopénie</span> → <span class=\"kw-alerte\">leishmaniose viscérale</span> (Kala-azar), principal <span class=\"kw-alerte\">diagnostic différentiel d’une leucémie aiguë</span></li><li><span class=\"kw-etio\">Strongyloïdose</span> sous <span class=\"kw-ci\">corticoïdes</span> / immunodépression → <span class=\"kw-alerte\">hyperinfection</span> par auto-infestation, potentiellement mortelle</li><li><span class=\"kw-alerte\">Crises convulsives</span> d’apparition tardive chez un migrant de zone d’endémie → <span class=\"kw-alerte\">neurocysticercose</span> (<span class=\"kw-etio\">Taenia solium</span>)</li><li><span class=\"kw-clinique\">Toux chronique</span> + <span class=\"kw-clinique\">AEG</span> + <span class=\"kw-clinique\">sueurs nocturnes</span> ± <span class=\"kw-clinique\">hémoptysie</span> → <span class=\"kw-etio\">tuberculose</span> (formes <span class=\"kw-alerte\">extra-pulmonaires</span> et <span class=\"kw-alerte\">multirésistantes</span> plus fréquentes)</li><li><span class=\"kw-clinique\">Diarrhée glairo-sanglante</span> + <span class=\"kw-alerte\">abcès hépatique amibien</span> → <span class=\"kw-etio\">amœbose</span> (<span class=\"kw-etio\">Entamoeba histolytica</span>)</li><li>Migrant hors couverture : prise en charge limitée aux <span class=\"kw-alerte\">soins urgents</span> tant que le <span class=\"kw-alerte\">pronostic vital</span> n’est pas engagé</li></ul>","principes":"<p><strong>Stratégie :</strong> croiser <span class=\"kw-clinique\">symptôme d’appel</span> × <strong>zone d’origine</strong> × <strong>délai depuis l’arrivée</strong>, sur un socle de <span class=\"kw-bio\">bilan systématique</span> de <span class=\"kw-def\">dépistage</span>.</p><p><strong>Bilan systématique — chez tout migrant</strong></p><ul><li><span class=\"kw-bio\">Sérologies VIH, VHB, VHC</span></li><li><span class=\"kw-bio\">Glycémie capillaire</span></li><li><span class=\"kw-bio\">Bandelette urinaire (BU)</span></li><li><span class=\"kw-bio\">NFS</span></li><li>Si provenance d’un pays à forte <span class=\"kw-def\">incidence</span> de <span class=\"kw-etio\">tuberculose</span> : <span class=\"kw-imagerie\">radiographie thoracique</span> + <span class=\"kw-bio\">IDR ou IGRA</span> chez <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">&lt; 18 ans</span> (recherche d’infection tuberculeuse latente)</li></ul><p><strong>Bilan contextuel — orienté</strong></p><ul><li>Afrique sub-saharienne : <span class=\"kw-bio\">sérologie de la schistosomose</span></li><li><span class=\"kw-clinique\">Fièvre</span> (origine compatible) : <span class=\"kw-bio\">frottis + goutte épaisse</span>, ou frottis + <span class=\"kw-bio\">TDR</span>, ou <span class=\"kw-bio\">PCR</span></li><li><span class=\"kw-clinique\">Troubles digestifs</span> : <span class=\"kw-bio\">3 EPS</span> (examens parasitologiques des selles)</li><li><span class=\"kw-clinique\">Hématurie</span> : <span class=\"kw-bio\">parasitologie des urines</span> + <span class=\"kw-bio\">sérologie</span> de la schistosomose</li></ul><p><strong>Première consultation de l’enfant migrant</strong></p><ul><li><span class=\"kw-clinique\">Courbe staturo-pondérale</span>, <span class=\"kw-clinique\">périmètre crânien</span>, état nutritionnel, développement psychomoteur</li><li>Bilan <span class=\"kw-ttt\">biologique</span> : <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">ferritinémie</span>, <span class=\"kw-bio\">électrophorèse de l’hémoglobine</span> (Afrique sub-saharienne), <span class=\"kw-bio\">glycémie</span>, <span class=\"kw-bio\">transaminases</span>, <span class=\"kw-bio\">créatinine</span>, <span class=\"kw-bio\">urée</span>, <span class=\"kw-bio\">ionogramme</span></li><li>Maladies transmissibles par la mère : <span class=\"kw-bio\">sérologies syphilis, VIH, VHB, VHC</span></li><li>Chez l’adolescent : recherche d’<span class=\"kw-etio\">IST</span> (<span class=\"kw-clinique\">syphilis</span>, gonocoque, Chlamydia, <span class=\"kw-etio\">VIH</span>) ; <span class=\"kw-bio\">test de grossesse</span> chez l’adolescente</li><li>Recherche de <span class=\"kw-etio\">tuberculose</span> : <span class=\"kw-imagerie\">RXT</span> + test immunologique</li><li>Si zone d’endémie : <span class=\"kw-bio\">EPS</span>, <span class=\"kw-bio\">sérologies</span> <span class=\"kw-bio\">anguillulose</span> et <span class=\"kw-bio\">bilharziose</span>, recherche de <span class=\"kw-etio\">paludisme</span></li><li>Évaluation d’un <span class=\"kw-clinique\">psychotraumatisme</span> ; recueil des vaccinations du pays d’origine</li></ul><p><strong>Prévention</strong></p><ul><li>Dépister et traiter l’<strong>entourage</strong> en cas de maladie contagieuse : <span class=\"kw-etio\">tuberculose</span>, <span class=\"kw-etio\">IST</span>, <span class=\"kw-etio\">teigne</span>, <span class=\"kw-etio\">parasitoses intestinales</span></li><li><span class=\"kw-ttt\">Vacciner l’entourage contre l’hépatite B</span> en cas de positivité</li><li>Hygiène alimentaire : lavage des mains, cuisson des aliments, éducation aux modes de transmission</li><li><span class=\"kw-clinique\">IST</span> : <span class=\"kw-ttt\">préservatif</span> masculin ou féminin, <span class=\"kw-ttt\">PrEP</span></li><li><span class=\"kw-clinique\">Paludisme</span> : <span class=\"kw-ttt\">prophylaxie antipalustre</span> en cas de retour dans le pays d’origine</li></ul><p><strong>Vaccinations</strong></p><ul><li><span class=\"kw-ttt\">Rattrapage du calendrier vaccinal français</span> pour tous</li><li><span class=\"kw-alerte\">Drépanocytaire</span> : <span class=\"kw-ttt\">pneumocoque</span> + <span class=\"kw-ttt\">grippe</span></li><li><span class=\"kw-alerte\">Asplénique</span> : <span class=\"kw-ttt\">pneumocoque</span> + <span class=\"kw-ttt\">méningocoque</span> + <span class=\"kw-ttt\">Haemophilus influenzae b</span> + <span class=\"kw-ttt\">grippe</span></li><li>Projet de pèlerinage à La Mecque : <span class=\"kw-ttt\">méningocoque</span></li><li>Retour en zone d’endémie amarile : <span class=\"kw-ttt\">fièvre jaune</span></li><li>Entourage d’un sujet atteint d’<span class=\"kw-ttt\">hépatite B</span> : <span class=\"kw-ttt\">vaccination anti-VHB</span></li><li><span class=\"kw-ttt\">BCG</span> chez <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">&lt; 15 ans</span> migrants nés en pays de forte <span class=\"kw-def\">prévalence</span>, et les enfants nés en France d’un parent migrant issu d’un pays de forte endémie</li></ul>","suivi":"<p><strong><span class=\"kw-etio\">Tuberculose</span> :</strong> <span class=\"kw-chiffre\">50 %</span> des cas français sont diagnostiqués chez des migrants ; <span class=\"kw-chiffre\">50 %</span> dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">5 premières années</span>, <span class=\"kw-chiffre\">25 %</span> dans les <span class=\"kw-chiffre\">2 premières années</span> → <span class=\"kw-def\">surveillance</span> prolongée.<br><strong>Mécanisme :</strong> surtout <span class=\"kw-clinique\">réactivation</span> d’une infection tuberculeuse latente ; formes <span class=\"kw-alerte\">extra-pulmonaires</span> et <span class=\"kw-alerte\">BK multirésistantes</span> (résistance à l’<span class=\"kw-ttt\">isoniazide</span> + la <span class=\"kw-ttt\">rifampicine</span>) plus fréquentes.<br><strong>Origines principales :</strong> Afrique sub-saharienne (<span class=\"kw-chiffre\">40 %</span>) · Maghreb (<span class=\"kw-chiffre\">30 %</span>).</p><p><strong>Enfant migrant</strong></p><ul><li><span class=\"kw-def\">Suivi</span> de la <span class=\"kw-clinique\">courbe staturo-pondérale</span>, de l’état nutritionnel et du développement psychomoteur (surtout enfant adopté)</li><li>Accompagnement du <span class=\"kw-clinique\">psychotraumatisme</span> lié au parcours migratoire</li></ul><p><strong>Vaccinations</strong></p><ul><li>Recueil des vaccinations réalisées dans le pays d’origine (fiabilité variable), puis <span class=\"kw-bio\">complément</span> selon le calendrier français</li><li>Une <span class=\"kw-ttt\">vaccination</span> dont la preuve manque est considérée comme non faite</li></ul>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-174.pdf","label":"Collège Pilly — Risques sanitaires liés aux eaux/aliments (item 174, PDF)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Migrant : primo-arrivant ou symptomatique — Bilan systématique pour tous + orientation selon le symptôme d’appel","detail":"<h4>CAT — démarche diagnostique chez le migrant — Symptôme d’appel × zone d’origine × délai depuis l’arrivée</h4>","branches":[{"to":"t-bilan","label":"Primo-arrivant asymptomatique","color":"blue"},{"to":"q-fievre","label":"Fièvre","color":"red"},{"to":"t-diarrhee","label":"Troubles digestifs / diarrhée","color":"amber"},{"to":"t-hematurie","label":"Hématurie","color":"amber"},{"to":"t-smg","label":"Fièvre prolongée + splénomégalie + pancytopénie","color":"amber"}]},{"id":"t-bilan","kind":"terminal","label":"Bilan systématique de dépistage","color":"blue","detail":"<h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Sérologies VIH, VHB, VHC</span></li><li><span class=\"kw-bio\">Glycémie capillaire</span>, <span class=\"kw-bio\">bandelette urinaire</span>, <span class=\"kw-bio\">NFS</span></li></ul><h4>Selon le <span class=\"kw-def\">terrain</span></h4><ul><li>Pays à forte <span class=\"kw-def\">incidence</span> de <span class=\"kw-etio\">tuberculose</span> : <span class=\"kw-imagerie\">radiographie thoracique</span> + <span class=\"kw-bio\">IDR ou IGRA</span> chez <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">&lt; 18 ans</span>. Afrique sub-saharienne : <span class=\"kw-bio\">sérologie de la schistosomose</span>.</li></ul><h4>Où</h4><ul><li><span class=\"kw-def\">CeGIDD</span>, <span class=\"kw-def\">CLAT</span>, <span class=\"kw-def\">PASS</span> ou laboratoire sur prescription, y compris sans droits sociaux ouverts.</li></ul>"},{"id":"q-fievre","kind":"decision","label":"Origine géographique compatible avec le paludisme ? — Le paludisme est à éliminer en premier","branches":[{"to":"t-palu","label":"Oui — zone d’endémie palustre","color":"red"},{"to":"t-fievre-autre","label":"Frottis négatif ou origine non palustre","color":"amber"}]},{"id":"t-palu","kind":"terminal","label":"Paludisme à éliminer en urgence","color":"red","detail":"<h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Frottis sanguin + goutte épaisse</span> en <span class=\"kw-alerte\">urgence</span> ; ou frottis + <span class=\"kw-bio\">TDR</span> ; ou <span class=\"kw-bio\">PCR</span> si disponible — à répéter si le premier examen est négatif.</li></ul><h4>Gravité</h4><ul><li><span class=\"kw-alerte\">Neuropaludisme</span> (<span class=\"kw-clinique\">fièvre</span> + <span class=\"kw-alerte\">trouble de la conscience</span>) à <span class=\"kw-etio\">P. falciparum</span> = <span class=\"kw-alerte\">urgence vitale</span>.</li></ul><h4>Renvoi</h4><ul><li>170 — <span class=\"kw-clinique\">Paludisme</span></li></ul>"},{"id":"t-fievre-autre","kind":"terminal","label":"Autres fièvres d’importation","color":"amber","detail":"<h4>À évoquer</h4><ul><li><span class=\"kw-etio\">Leishmaniose viscérale</span> si <span class=\"kw-clinique\">splénomégalie</span> + <span class=\"kw-bio\">pancytopénie</span></li><li><span class=\"kw-etio\">Amœbose</span> avec <span class=\"kw-clinique\">abcès hépatique amibien</span></li><li><span class=\"kw-etio\">Tuberculose</span>, <span class=\"kw-clinique\">primo-infection</span> <span class=\"kw-etio\">VIH</span></li></ul><h4>Conduite</h4><ul><li>Bilan orienté : <span class=\"kw-bio\">sérologies</span> (leishmaniose, amœbose) et <span class=\"kw-imagerie\">échographie hépatique</span> selon le point d’appel.</li></ul>"},{"id":"t-diarrhee","kind":"terminal","label":"Diarrhée du migrant","color":"amber","detail":"<h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">3 examens parasitologiques des selles (EPS)</span> sur <span class=\"kw-chiffre\">3 jours</span> différents.</li></ul><h4>À évoquer</h4><ul><li><span class=\"kw-etio\">Amœbose</span> : <span class=\"kw-clinique\">diarrhée</span> <span class=\"kw-clinique\">glairo-sanglante</span> ± <span class=\"kw-clinique\">abcès hépatique</span></li><li><span class=\"kw-etio\">Giardose</span> : <span class=\"kw-clinique\">diarrhée</span> chronique avec <span class=\"kw-clinique\">malabsorption</span></li><li>Helminthoses intestinales : ascaridiose, <span class=\"kw-etio\">ankylostomose</span> (<span class=\"kw-clinique\">anémie martiale</span>), anguillulose, téniasis</li></ul><h4>Renvoi</h4><ul><li>176 — Diarrhées infectieuses</li></ul>"},{"id":"t-hematurie","kind":"terminal","label":"Schistosomose urinaire","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Hématurie</span> ; notion de <span class=\"kw-etio\">baignade en eau douce</span> ; <span class=\"kw-etio\">S. haematobium</span>.</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Parasitologie des urines</span> (recherche d’œufs) + <span class=\"kw-bio\">sérologie de la schistosomose</span>.</li></ul>"},{"id":"t-smg","kind":"terminal","label":"Leishmaniose viscérale (Kala-azar)","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Fièvre prolongée</span> + <span class=\"kw-clinique\">splénomégalie</span> + <span class=\"kw-bio\">pancytopénie</span> ; transmise par le phlébotome.</li></ul><h4>Piège</h4><ul><li>Principal <span class=\"kw-alerte\">diagnostic différentiel d’une leucémie aiguë</span> chez le migrant.</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Sérologie leishmaniose</span> et recherche du parasite (<span class=\"kw-ttt\">ponction</span> médullaire).</li></ul>"}]},"cards":[{"i":"31ac068f646f","n":174,"o":"174-1","u":"Définition","t":"Connaître la définition d’un migrant (personne immigrée)","q":"Qu'est-ce qu'un 'réfugié' et quel organisme attribue ce statut en France ?","a":"<div class=\"notion-course\"><ul><li>Personne reconnue réfugiée en raison de craintes fondées de persécutions selon la Convention de Genève. En France, reconnaissance par l’OFPRA ou, sur recours, la CNDA. Un demandeur d’asile attend la décision sur sa demande.</li></ul></div>"},{"i":"648c2dabd52c","n":174,"o":"174-1","u":"Définition","t":"Connaître la définition d’un migrant (personne immigrée)","q":"Quelle est la définition statistique d’un immigré selon l’INSEE ?","a":"<div class=\"notion-course\"><ul><li>Au sens statistique INSEE, un immigré est né étranger à l’étranger et réside en France ; il peut avoir acquis la nationalité française. Ne pas confondre immigré et étranger, ni imposer un délai universel d’un an à cette définition.</li></ul></div>"},{"i":"81fe64a8dd87","n":174,"o":"174-1","u":"Définition","t":"Connaître la définition d’un migrant (personne immigrée)","q":"Quelle est la définition d'un 'étranger' en France, et en quoi diffère-t-elle de celle d'un migrant ?","a":"<div class=\"notion-course\"><p>Un étranger est une personne qui <strong>ne dispose pas de la nationalité française</strong>. Contrairement au migrant, elle peut être <strong>née en France</strong> et son statut est une <strong>notion administrative et juridique</strong>. Elle peut être en situation régulière ou irrégulière.</p></div>"},{"i":"c9becce86366","n":174,"o":"174-1","u":"Définition","t":"Connaître la définition d’un migrant (personne immigrée)","q":"Comment est défini un 'enfant migrant' et quelles sont les situations concernées ?","a":"<div class=\"notion-course\"><p>Un enfant migrant est tout enfant <strong>vivant temporairement ou durablement dans un pays où il n'est pas né</strong>. Cela inclut l'enfant migrant accompagné de ses parents, l'enfant adopté, ou le <strong>mineur non accompagné (MNA) / mineur isolé étranger (MIE)</strong>.</p></div>"},{"i":"1930374abb1a","n":174,"o":"174-2","u":"Physiopathologie","t":"Connaître les principales pathologies infectieuses des migrants","q":"Quel est le piège à connaître concernant la strongyloïdose chez un migrant sous corticothérapie ou immunosuppression ?","a":"<div class=\"notion-course\"><p>Le piège à connaître est le risque d'<strong>hyperinfection mortelle</strong> en cas de strongyloïdose (<em>Strongyloides stercoralis</em>) chez un migrant sous <strong>corticothérapie</strong> ou immunosuppression. Ce parasite a la capacité de s'auto-infester. Il est donc recommandé de dépister la <strong>sérologie anguillulose</strong> avant toute corticothérapie chez un migrant provenant d'une zone d'endémie.</p></div>"},{"i":"3c7cef50b354","n":174,"o":"174-2","u":"Physiopathologie","t":"Connaître les principales pathologies infectieuses des migrants","q":"Comment classifie-t-on les pathologies infectieuses chez le migrant selon leur mécanisme d'acquisition ?","a":"<div class=\"notion-course\"><p>Les pathologies infectieuses chez le migrant sont classées en deux catégories selon leur mécanisme d'acquisition :</p><ul><li>Les <strong>infections d'importation</strong>, contractées dans le pays d'origine.</li><li>Les <strong>infections acquises sur le territoire national</strong>.</li></ul></div>"},{"i":"a8153d0e848a","n":174,"o":"174-2","u":"Physiopathologie","t":"Connaître les principales pathologies infectieuses des migrants","q":"Quelles sont les principales infections bactériennes et virales d'importation chez le migrant ?","a":"<div class=\"notion-course\"><p>Les principales infections bactériennes et virales d'importation chez le migrant sont :</p><ul><li>Bactéries : <strong>tuberculose</strong>, <strong>lèpre</strong>.</li><li>Virus : <strong>VIH</strong>, <strong>VHB</strong>, <strong>VHC</strong>.</li></ul></div>"},{"i":"c13e3b2ea140","n":174,"o":"174-2","u":"Physiopathologie","t":"Connaître les principales pathologies infectieuses des migrants","q":"Quelles sont les principales protozooses et helminthoses d'importation que l'on peut retrouver chez le migrant ?","a":"<div class=\"notion-course\"><p>Les principales infections d'importation chez le migrant incluent :</p><ul><li>Protozooses : <strong>paludisme</strong>, <strong>amœbose</strong>, <strong>giardose</strong>, <strong>leishmanioses</strong> (cutanée, viscérale), <strong>trypanosomoses</strong> (maladie du sommeil, maladie de Chagas).</li><li>Helminthoses intestinales : <strong>ascaridiose</strong>, <strong>ankylostomose</strong>, <strong>strongyloïdose</strong> (anguillulose), <strong>téniasis</strong>.</li><li>Helminthoses tissulaires : <strong>filarioses</strong> (loase, lymphatiques, onchocercose), <strong>schistosomoses</strong>, <strong>hydatidose hépatique</strong>.</li></ul></div>"},{"i":"c587e721a5a0","n":174,"o":"174-2","u":"Physiopathologie","t":"Connaître les principales pathologies infectieuses des migrants","q":"Quelle est l'urgence à toujours évoquer devant une fièvre et des troubles de conscience chez un migrant de retour d'une zone d'endémie palustre ?","a":"<div class=\"notion-course\"><p>Devant une fièvre avec troubles de conscience chez un migrant de retour d'une zone d'endémie palustre, il faut <span class=\"nc-red nc-bold\">systématiquement</span> évoquer le <strong>neuropaludisme</strong>. Il s'agit d'une urgence nécessitant la réalisation d'un <strong>frottis sanguin et d'une goutte épaisse en urgence (&lt; 2 heures)</strong>, car le <strong>paludisme grave à <em>P. falciparum</em></strong> est une urgence vitale.</p></div>"},{"i":"c90aff33a805","n":174,"o":"174-2","u":"Physiopathologie","t":"Connaître les principales pathologies infectieuses des migrants","q":"Quelles sont les principales infections acquises sur le territoire national chez le migrant ?","a":"<div class=\"notion-course\"><p>Les principales infections acquises sur le territoire national chez le migrant sont :</p><ul><li>Infections respiratoires et intestinales, bactériennes et virales (plus fréquentes et graves).</li><li><strong><span class=\"nc-purple nc-bold\">Tuberculose</span> acquise en France</strong>.</li><li><strong>Infections Sexuellement Transmissibles (IST)</strong>, avec un risque non rare d'acquisition du VIH et de la <span class=\"nc-purple nc-bold\">tuberculose</span>.</li><li>Infections <strong>pneumococciques</strong> et <strong>salmonelloses non typhiques</strong> chez le drépanocytaire.</li></ul></div>"},{"i":"219728644632","n":174,"o":"174-4","u":"Prise en charge","t":"Connaître les modalités d’accès aux soins des migrants","q":"Quels sont les trois dispositifs de couverture maladie principaux pour l'accès aux soins des migrants en France, et leurs conditions d'éligibilité respectives ?","a":"<div class=\"notion-course\"><ul><li>Selon situation : assurance maladie/<span class=\"nc-green_bg\">PUMa</span> pour les personnes remplissant les conditions de régularité et de résidence ; <span class=\"nc-green_bg\">AME</span> sous conditions pour les personnes en situation irrégulière ; dispositif de soins urgents pendant une absence de droits ouverts.</li><li>Les conditions et délais doivent être vérifiés avec CPAM/PASS. Les soins urgents comprennent le risque d’altération grave et durable de la santé, et certaines situations liées à la grossesse ou aux mineurs ; ils ne se limitent pas au pronostic vital immédiat.</li></ul></div>"},{"i":"a42fa73f0b8c","n":174,"o":"174-4","u":"Prise en charge","t":"Connaître les modalités d’accès aux soins des migrants","q":"Quelles sont les structures de soins gratuites spécifiquement dédiées ou utiles pour l'accès aux soins des migrants en France ?","a":"<div class=\"notion-course\"><p>Plusieurs structures offrent des soins gratuits et accessibles :</p><ul><li>Les <strong><span class=\"nc-yellow_bg\">PASS</span> (Permanences d'Accès aux Soins de Santé)</strong> : accueil hospitalier des personnes sans couverture maladie ou précaires.</li><li>Les <strong><span class=\"nc-yellow_bg\">CeGIDD</span> (<span class=\"nc-yellow_bg\">Centres Gratuits d'Information, de Dépistage et de Diagnostic</span>)</strong> : dépistage gratuit et anonyme des IST, VIH, VHB, VHC.</li><li>Les <strong>CLAT (<span class=\"nc-purple_bg\">Centres de Lutte Anti-Tuberculeuse</span>)</strong> : dépistage et prise en charge gratuite de la tuberculose.</li><li>Les <strong>PMI (<span class=\"nc-green_bg\">Protection Maternelle et Infantile</span>)</strong> : suivi de grossesse et de l'enfant de 0 à 6 ans, vaccinations.</li><li>Les <strong>CPEF (<span class=\"nc-green_bg\">Centres de Planification et d'Éducation Familiale</span>)</strong> : contraception, IVG, IST.</li><li>Les <strong>CMP (Centres Médico-Psychologiques)</strong> : soins en santé mentale, notamment pour le psychotraumatisme migratoire.</li><li>Les <strong><span class=\"nc-yellow_bg\">Centres de vaccination</span></strong> : pour le rattrapage du calendrier vaccinal.</li></ul></div>"},{"i":"e9b082fe4a5f","n":174,"o":"174-4","u":"Prise en charge","t":"Connaître les modalités d’accès aux soins des migrants","q":"Quelle est la particularité de la prise en charge d'un mineur non accompagné (MNA) migrant pour son accès aux soins ?","a":"<div class=\"notion-course\"><ul><li>Évaluation rapide des besoins, mise à l’abri et protection de l’enfance/ASE selon situation, accompagnement pour ouvrir les droits et organiser les soins. Ne pas laisser le mineur gérer seul ces démarches.</li><li>L’origine étrangère ne justifie pas à elle seule un isolement. Recherche de BHRe et précautions selon les expositions, notamment une hospitalisation à l’étranger, le portage connu et l’avis d’hygiène.</li></ul></div>"},{"i":"0d312236992e","n":174,"o":"174-5","u":"Diagnostic positif","t":"Connaître les principales pathologies à dépister chez les migrants","q":"Quelles sont les principales pathologies à dépister chez un migrant venant d'Afrique subsaharienne, selon l'Item 174 ?","a":"<div class=\"notion-course\"><p>Les principales pathologies à dépister pour un migrant originaire d'Afrique subsaharienne (risque maximal) incluent :</p><ul><li><strong>Bactéries/virus</strong> : Tuberculose, portage chronique du <strong><span class=\"nc-purple_bg nc-bold\">VHB</span></strong> (très fréquent), <span class=\"nc-purple_bg nc-bold\">VHC</span>, VIH (prévalence élevée).</li><li><strong>Helminthoses</strong> : Ascaridiose, ankylostomose, anguillulose, téniasis, <strong>filarioses (<em>Loa loa</em>, <em>W. bancrofti</em>, <em>Onchocerca</em>)</strong>, <strong>schistosomoses urinaire et intestinale</strong>, hydatidose hépatique.</li><li><strong>Protozooses</strong> : <strong>Paludisme (surtout <em>P. falciparum</em>)</strong>, leishmanioses, trypanosomose africaine (maladie du sommeil), amœbose, giardose.</li><li><strong>Ectoparasites</strong> : Gale (surtout chez l'enfant).</li></ul><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Les dépistages sont adaptés aux expositions et au parcours, avec accord de la personne ; les cartes historiques illustrent des risques et ne remplacent pas une évaluation actuelle. Ne pas prescrire automatiquement l’ensemble des examens parasitaires à toute personne migrante.</li><li>Les chiffres et la cartographie du tableau sont des repères historiques du Pilly 2023 ; ils ne constituent pas une surveillance épidémiologique en temps réel ni une liste d’examens à imposer selon la seule origine.</li></ul></div></div>"},{"i":"57fc32a97b31","n":174,"o":"174-5","u":"Diagnostic positif","t":"Connaître les principales pathologies à dépister chez les migrants","q":"Quels sont les dépistages systématiques à réaliser chez tout migrant primo-arrivant, indépendamment de sa zone géographique d'origine, selon l'Item 174 ?","a":"<div class=\"notion-course\"><p>Chez tout migrant primo-arrivant, un bilan systématique commun doit être réalisé, incluant :</p><ul><li>Des <strong>sérologies VIH, VHB, VHC</strong> pour dépister l'infection par le VIH, le portage chronique du VHB et l'hépatite C.</li><li>Une <strong>glycémie capillaire</strong> pour dépister un diabète, souvent méconnu.</li><li>Une <strong>bandelette urinaire (BU)</strong> pour rechercher une infection urinaire, une hématurie (pouvant orienter vers une schistosomose) ou une protéinurie.</li><li>Une <strong>NFS</strong> (Numération Formule Sanguine) pour l'exploration de cytopénies, d'une anémie martiale ou d'une éosinophilie (suggérant des helminthoses).</li><li>Une <strong>radiographie thoracique (<span class=\"nc-blue_bg\">RXT</span>)</strong> et une <strong>IDR</strong> ou un <strong>IGRA</strong> chez les moins de 18 ans, si le migrant provient d'un pays à incidence élevée de <span class=\"nc-purple nc-bold\">tuberculose</span>, pour la recherche de <span class=\"nc-purple nc-bold\">tuberculose</span>-maladie ou d'infection tuberculeuse latente.</li></ul><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Les dépistages sont adaptés aux expositions et au parcours, avec accord de la personne ; les cartes historiques illustrent des risques et ne remplacent pas une évaluation actuelle. Ne pas prescrire automatiquement l’ensemble des examens parasitaires à toute personne migrante.</li><li>Les chiffres et la cartographie du tableau sont des repères historiques du Pilly 2023 ; ils ne constituent pas une surveillance épidémiologique en temps réel ni une liste d’examens à imposer selon la seule origine.</li></ul></div></div>"},{"i":"e668a222fa4e","n":174,"o":"174-5","u":"Diagnostic positif","t":"Connaître les principales pathologies à dépister chez les migrants","q":"Quelle est l'épidémiologie de la tuberculose chez le migrant en France et quelles sont ses particularités, selon l'Item 174 ?","a":"<div class=\"notion-course\"><p>L'épidémiologie de la <span class=\"nc-purple nc-bold\">tuberculose</span> chez le migrant en France présente les caractéristiques suivantes :</p><ul><li><strong>50 % des cas de <span class=\"nc-purple nc-bold\">tuberculose</span></strong> en France sont diagnostiqués chez des migrants.</li><li>Parmi eux, <strong>50 %</strong> sont diagnostiqués dans les <strong>5 premières années</strong> suivant l'arrivée, et <strong>25 %</strong> dans les <strong>2 premières années</strong>.</li><li>Les origines principales sont l'<strong>Afrique subsaharienne (40 %)</strong> et le <strong>Maghreb (30 %)</strong>.</li><li>Le mécanisme dominant est la <strong>réactivation d'une infection tuberculeuse latente</strong> contractée au pays d'origine.</li><li>Les particularités incluent des <strong>formes extra-pulmonaires plus fréquentes</strong> et une incidence plus élevée de BK multirésistante (résistance à l'<strong>isoniazide et à la rifampicine</strong>).</li></ul><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Les dépistages sont adaptés aux expositions et au parcours, avec accord de la personne ; les cartes historiques illustrent des risques et ne remplacent pas une évaluation actuelle. Ne pas prescrire automatiquement l’ensemble des examens parasitaires à toute personne migrante.</li><li>Les chiffres et la cartographie du tableau sont des repères historiques du Pilly 2023 ; ils ne constituent pas une surveillance épidémiologique en temps réel ni une liste d’examens à imposer selon la seule origine.</li></ul></div></div>"},{"i":"efa16d083b24","n":174,"o":"174-5","u":"Diagnostic positif","t":"Connaître les principales pathologies à dépister chez les migrants","q":"Quels sont les examens complémentaires à ajouter au bilan systématique chez un migrant primo-arrivant issu d'Afrique subsaharienne, et en fonction de symptômes spécifiques ?","a":"<div class=\"notion-course\"><p>En fonction du contexte, des examens doivent être ajoutés :</p><ul><li>Pour une origine <strong>d'Afrique subsaharienne</strong> : une <strong><span class=\"nc-blue_bg\">sérologie de la schistosomose</span></strong>.</li><li>En cas de <strong>fièvre</strong> et d'origine géographique compatible : frottis sanguin et goutte épaisse ou frottis et TDR ou PCR pour le <strong>paludisme</strong>.</li><li>En cas de <strong>troubles digestifs (diarrhée)</strong> : <strong>3 examens parasitologiques des selles (EPS)</strong>.</li><li>En cas d'<strong>hématurie</strong> : <span class=\"nc-blue_bg\">parasitologie des urines</span> et <span class=\"nc-blue_bg\">sérologie de la </span><strong><span class=\"nc-blue_bg\">schistosomose</span></strong>.</li></ul><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Les dépistages sont adaptés aux expositions et au parcours, avec accord de la personne ; les cartes historiques illustrent des risques et ne remplacent pas une évaluation actuelle. Ne pas prescrire automatiquement l’ensemble des examens parasitaires à toute personne migrante.</li><li>Les chiffres et la cartographie du tableau sont des repères historiques du Pilly 2023 ; ils ne constituent pas une surveillance épidémiologique en temps réel ni une liste d’examens à imposer selon la seule origine.</li></ul></div></div>"},{"i":"203d289a936f","n":174,"o":"174-6","u":"Prise en charge","t":"Connaître les principes de la prévention à mettre en place chez les migrants","q":"Quelles mesures spécifiques de dépistage faut-il envisager au sein de l'entourage d'un migrant suspecté de pathologie infectieuse contagieuse ?","a":"<div class=\"notion-course\"><p>En cas de maladie contagieuse chez le migrant, il faut envisager :</p><ul><li>Un <strong>dépistage par examen médical</strong> du patient et de son entourage.</li><li>Le dépistage et le traitement de l'entourage en cas de maladies comme la <strong><span class=\"nc-purple nc-bold\">tuberculose</span></strong>, les <strong>IST</strong>, la <strong>teigne</strong> ou les <strong>parasitoses intestinales</strong>.</li><li>La vaccination de l'entourage contre l'<strong>hépatite B</strong> en cas de positivité du migrant.</li></ul></div>"},{"i":"adb88db14a2b","n":174,"o":"174-6","u":"Prise en charge","t":"Connaître les principes de la prévention à mettre en place chez les migrants","q":"Quels conseils d'hygiène alimentaire et de prévention des IST doit-on donner aux migrants ?","a":"<div class=\"notion-course\"><p>Concernant l'hygiène alimentaire :</p><ul><li>Insister sur le <strong>lavage des mains</strong>.</li><li>La <strong>cuisson des aliments</strong>.</li><li>Expliquer les principaux risques, leurs modes de transmission et la prévention.</li></ul><p>Pour la prévention des IST :</p><ul><li>Promouvoir l'utilisation du <strong>préservatif</strong> masculin ou féminin.</li><li>Informer sur la <strong>PrEP</strong> (Prophylaxie Pré-Exposition).</li><li>Utiliser l'aide d'un <strong>interprète</strong> si nécessaire et faire appel aux <strong>associations spécialisées</strong>.</li></ul></div>"},{"i":"adb9b3fcad23","n":174,"o":"174-6","u":"Prise en charge","t":"Connaître les principes de la prévention à mettre en place chez les migrants","q":"Quels sont les axes principaux de la prévention des pathologies infectieuses chez le migrant ?","a":"<div class=\"notion-course\"><p>La prévention chez le migrant combine plusieurs axes :</p><ul><li>Le <strong>dépistage et le traitement de l'entourage</strong>.</li><li>L'<strong>éducation à l'hygiène</strong> (notamment alimentaire).</li><li>La <strong>prévention des IST</strong> (Infections Sexuellement Transmissibles).</li><li>La <strong>prévention du paludisme</strong>.</li></ul></div>"},{"i":"c030901402d1","n":174,"o":"174-6","u":"Prise en charge","t":"Connaître les principes de la prévention à mettre en place chez les migrants","q":"Quelle est la particularité de la prévention du paludisme chez le migrant, notamment en cas de retour au pays d'origine ?","a":"<div class=\"notion-course\"><p>La prévention du paludisme chez le migrant implique une <strong>prophylaxie antipalustre</strong> en cas de retour dans le <strong>pays d'origine</strong>, car un migrant ayant vécu longtemps hors zone d'endémie a perdu son immunité naturelle. Il doit recevoir une prophylaxie antipalustre <strong>comme tout voyageur</strong> et une <strong>mise à jour vaccinale</strong> adaptée à la destination. Il est crucial d'expliquer le mode de transmission de la maladie.</p></div>"},{"i":"aec26610b29c","n":174,"o":"174-3","u":"Diagnostic positif","t":"Connaître les arguments épidémio-cliniques et les stratégies d’examens complémentaires pour identifier les principales pathologies infectieuses des migrants","q":"Quels sont les points essentiels concernant les arguments épidémio-cliniques et les stratégies d’examens complémentaires pour identifier les principales pathologies infectieuses des migrants ?","a":"<div class=\"notion-course\"><p>L'identification d'une pathologie infectieuse chez le migrant repose sur le croisement de trois axes : <strong>zone géographique d'origine</strong> × <strong>délai depuis l'arrivée</strong> × <strong>symptôme d'appel</strong>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Arguments épidémiologiques</h4>\n      <ul>\n        <li><strong>Zone d'origine</strong> — oriente le spectre <span>parasitaire</span> (l'<span>Afrique sub-saharienne</span> cumule le risque maximal et le plus de pathologies).</li>\n        <li><strong>Délai depuis l'arrivée</strong> — une infection d'importation se révèle volontiers dans <span>les</span> premiers mois ou années.</li>\n        <li><strong>Retour régulier au pays</strong> (VFR) — réexposition et perte de l'immunité antérieurement <span>acquise</span>.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Symptôme d'appel → examens à orienter</h4>\n      <table>\n        <thead><tr><th>Symptôme d'appel</th><th>Stratégie d'examens complémentaires</th></tr></thead>\n        <tbody>\n          <tr><td><span>Fièvre</span> (origine géographique compatible)</td><td><span>Frottis sanguin + goutte épaisse</span> ; ou <span>TDR-paludisme</span> ; ou <span>PCR</span> si disponible — à répéter si premier examen négatif</td></tr>\n          <tr><td><span>Troubles digestifs</span> / <span>diarrhée</span></td><td><span>3 examens parasitologiques des selles (EPS)</span> sur <span>3 jours</span> différents</td></tr>\n          <tr><td><span>Hématurie</span></td><td><span><span class=\"nc-blue_bg\">Parasitologie des urines</span></span> + <span><span class=\"nc-blue_bg\">sérologie de la schistosomose</span></span></td></tr>\n          <tr><td><span>Anémie microcytaire</span> inexpliquée</td><td>Évoquer <span>ankylostomose</span> et schistosomose digestive (EPS, <span>sérologie</span>) <strong>avant</strong> <span>endoscopie</span></td></tr>\n          <tr><td><span>Fièvre + splénomégalie + pancytopénie</span></td><td><span>Sérologie leishmaniose</span> + recherche d'<span>amastigotes</span> sur <span>ponction</span> médullaire</td></tr>\n          <tr><td><span>Éosinophilie</span></td><td>Bilan d'helminthose : <span class=\"nc-yellow_bg\">EPS</span>, <span>sérologies</span> (anguillulose, schistosomose, filaires)</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Associations cliniques discriminantes</h4>\n      <table>\n        <thead><tr><th>Pathologie</th><th>Mot-clé évocateur</th></tr></thead>\n        <tbody>\n          <tr><td><span>Paludisme</span></td><td><span>Fièvre</span> au retour de zone d'endémie ; <span>thrombopénie</span> ; <span>splénomégalie</span></td></tr>\n          <tr><td><span>Amœbose</span></td><td><span>Diarrhée</span> <span>glairo-sanglante</span> ; <span>abcès hépatique amibien</span> (<span>échographie</span>)</td></tr>\n          <tr><td><span>Schistosomose</span></td><td><span>Hématurie macroscopique terminale</span> (<em>S. haematobium</em>) ; baignade en eau douce</td></tr>\n          <tr><td><span>Ankylostomose</span></td><td><span>Anémie ferriprive chronique</span> inexpliquée ; transmission transcutanée</td></tr>\n          <tr><td><span>Strongyloïdose</span></td><td><span>Larva currens</span> ; <span>hyperinfection sous corticoïdes</span></td></tr>\n          <tr><td><span>Leishmaniose viscérale</span></td><td><span>Fièvre prolongée + splénomégalie majeure + pancytopénie</span> (Kala-azar)</td></tr>\n          <tr><td><span>Cysticercose</span> (<em>T. solium</em>)</td><td><span>Crises convulsives d'apparition tardive</span> ; <span>IRM</span> : kystes en cocarde</td></tr>\n          <tr><td><span>Filarioses</span></td><td><span>Œdème</span> de Calabar (<em>Loa loa</em>) ; éléphantiasis (<em>W. bancrofti</em>) ; cécité des rivières (<em>Onchocerca</em>)</td></tr>\n          <tr><td><span>Maladie de Chagas</span></td><td><span>Cardiomyopathie dilatée</span> + mégaœsophage / mégacolon ; Amérique latine</td></tr>\n          <tr><td><span>Tuberculose</span></td><td><span>Toux &gt; 3 semaines</span> ; <span>AEG</span> ; sueurs nocturnes ; formes extra-pulmonaires fréquentes</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>Piège — leishmaniose viscérale.</strong> Devant <span>fièvre prolongée + splénomégalie majeure + pancytopénie</span> chez un migrant, le Kala-azar est le <span>principal diagnostic différentiel d'une leucémie aiguë</span>. Évoquer la <span>sérologie leishmaniose</span> et la recherche d'amastigotes avant de conclure à une hémopathie.\n      </div>\n      <div class=\"callout callout-warn\">\n        <strong>Piège — cysticercose cérébrale.</strong> Une <span>épilepsie d'apparition tardive</span> chez un migrant de zone d'endémie (<em>T. solium</em>) doit faire évoquer une neurocysticercose : <span>IRM cérébrale</span> + <span>sérologie</span> cysticercose.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 170 — <span>Paludisme</span> · 176 — <span>Diarrhée</span> infectieuse · 159 — <span>Tuberculose</span> Enfant / Adulte</em></p></div>"},{"i":"a9ba8b1abb02","n":174,"o":"174-7","u":"Prise en charge","t":"Connaître les principaux vaccins à mettre à jour","q":"Quels sont les points essentiels concernant les principaux vaccins à mettre à jour ?","a":"<div class=\"notion-course\"><p>La mise à jour vaccinale du migrant vise d'abord le <strong><span>rattrapage du calendrier vaccinal français</span></strong>, complété par des vaccinations ciblées selon le <span>terrain</span> et le projet de vie.</p>\n\n      <table>\n        <thead><tr><th>Population / situation</th><th>Vaccins</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Tous <span>les</span> migrants</strong></td><td>Mise à jour et <span>rattrapages</span> pour satisfaire le <strong><span>calendrier vaccinal</span> français</strong> en vigueur</td></tr>\n          <tr><td><strong><span>Drépanocytaires</span></strong></td><td><span>Pneumocoque</span> + <span>grippe</span></td></tr>\n          <tr><td><strong><span>Sujets aspléniques</span></strong></td><td><span>Pneumocoque</span> + <span>méningocoque</span> + <em><span>Haemophilus</span> influenzae</em> b + <span>grippe</span></td></tr>\n          <tr><td><strong>Projet de pèlerinage à La Mecque</strong></td><td><span>Méningocoque</span></td></tr>\n          <tr><td><strong>Retour en zone d'endémie amarile</strong></td><td><span>Fièvre jaune</span></td></tr>\n          <tr><td><strong>Entourage d'un sujet atteint d'<span>hépatite B</span></strong></td><td><span>Vaccination</span> de l'<strong>entourage familial</strong> contre l'<span>hépatite B</span></td></tr>\n          <tr><td><strong>BCG</strong></td><td><span>BCG</span> chez <span>les</span> sujets de <span>&lt; 15 ans</span> migrants nés dans un pays de <span>forte prévalence</span>, et chez les enfants nés en France d'un parent migrant issu d'un pays de <span>forte endémie</span></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> <span>Les</span> carnets de <span>vaccination</span> du pays d'origine sont de fiabilité variable : recueillir les vaccinations déjà réalisées, puis compléter selon le calendrier français. Une vaccination dont la preuve manque est considérée comme non faite.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 146 — <span>Vaccination</span></em></p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Un schéma vaccinal documenté et valide compte : ne pas recommencer systématiquement une série. En l’absence de document, organiser un rattrapage adapté à l’âge et au calendrier, sans présumer la fiabilité d’un carnet à partir de la seule nationalité.</li></ul></div></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/1cb37f85d94181dda862f86ef4e825c3?pvs=204","reviewedAt":"2026-10-16","batch":"digestive-infectious-50","verification":"reviewed","note":"Relecture et contrôles du lot réalisés. LiSA : copies locales ; ordinateur et format iPad simulé."}};
